do $$ declare v_product_id uuid;v_order_id uuid;begin select p.id into v_product_id from public.products p where lower(btrim(p.name))='teste' and not p.active and not exists(select 1 from public.sale_items si where si.product_id=p.id) order by p.created_at desc limit 1;if v_product_id is null then return;end if;for v_order_id in select distinct poi.purchase_order_id from public.purchase_order_items poi where poi.product_id=v_product_id loop delete from public.purchase_receipts where purchase_order_item_id in(select id from public.purchase_order_items where product_id=v_product_id and purchase_order_id=v_order_id);delete from public.purchase_order_items where product_id=v_product_id and purchase_order_id=v_order_id;if not exists(select 1 from public.purchase_order_items where purchase_order_id=v_order_id) then delete from public.purchase_orders where id=v_order_id;end if;end loop;delete from public.inventory_history where product_id=v_product_id;delete from public.inventory_movements where product_id=v_product_id;delete from public.partner_movements where product_id=v_product_id;delete from public.stock_reservations where product_id=v_product_id;delete from public.stock_balances where product_id=v_product_id;delete from public.supplier_orders where product_id=v_product_id;insert into public.audit_events(entity_type,entity_id,action,details) values('product',v_product_id,'legacy_test_record_removed',jsonb_build_object('name','Teste','reason','Migrado conceitualmente para Área de Teste isolada'));delete from public.products where id=v_product_id;end$$;
